import{z as s,x as B,o as t,c as d,q as r,j as i,D as e,d as A,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"零知识直觉","description":"","frontmatter":{"title":"零知识直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/zero-knowledge-intuition.md","filePath":"cs/zero-knowledge-intuition.md","lastUpdated":1791063341000}'),p={name:"cs/zero-knowledge-intuition.md"};function F(u,a,D,m,h,c){const o=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="零知识直觉" tabindex="-1">零知识直觉 <a class="header-anchor" href="#零知识直觉" aria-label="Permalink to &quot;零知识直觉&quot;">​</a></h1><div class="epigraph"><p>证明者让验证者相信命题成立，而不多给能转述给第三人的证据。模拟器能在不知道证人时伪造与真实不可区分的对话——这就是「零知识」。</p><footer>—— Goldwasser, Micali and Rackoff, The Knowledge Complexity of Interactive Proof Systems, 1985, 1989</footer></div><p>上一课<a href="/cs/post-quantum-kyber">后量子</a>换了陷门。缺口是<strong>另一类协议目标</strong>：不传输证人，只传输可验的对话。主干没有 ZK 课；本课直觉，不写电路到多项式的全套。与<a href="/cs/interactive-proofs">交互证明</a>的复杂度课只点名，不重推 IP=PSPACE。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>签名证明「持有私钥的人认过消息」，但签名本身可转述。ZK：验证者自己能模拟视图，故不能拿对话去说服别人（在适当模型下）。缺口是完备性、可靠性、零知识三条，不是具体 zk-SNARK 产品。</p><h3 id="可靠性-零知识" tabindex="-1">可靠性≠零知识 <a class="header-anchor" href="#可靠性-零知识" aria-label="Permalink to &quot;可靠性≠零知识&quot;">​</a></h3><p>可靠性：假命题不能过。零知识：真命题的对话不泄漏证人。可以强可靠而完全不零知识（直接给证人）。</p><p><span class="marginnote">直觉类比：三个性质像给协议做三道体检。完备性查&quot;真话者能不能过&quot;（必须能）；可靠性查&quot;说谎者能不能骗过&quot;（概率要压到可忽略）；零知识查&quot;过关的人身上有没有掉出多余情报&quot;（模拟器能伪造同样对话，就说明没掉）。</span></p><p><span class="marginnote">GMR 1985/1989。Schnorr 协议是离散对数的经典 Σ 协议形状，本课只当例子点名，不给用于伪造的代数步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用「洞穴/口令」隐喻后立刻升到游戏：模拟器、提取器。指出非交互需要 Fiat–Shamir 与随机预言机假设。后课承诺是 Σ 协议的零件。</p>',12)),(t(),i(n,null,{default:e(()=>[l(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E8%AF%81%E4%BA%BA%22%5D%20--%3E%20P%5B%22%E8%AF%81%E6%98%8E%E8%80%85%22%5D%0A%20%20P%20--%3E%20V%5B%22%E9%AA%8C%E8%AF%81%E8%80%85%E5%8F%AA%E4%BF%A1%E5%91%BD%E9%A2%98%22%5D%0A%20%20S%5B%22%E6%A8%A1%E6%8B%9F%E5%99%A8%E6%97%A0%E8%AF%81%E4%BA%BA%22%5D%20--%3E%20VIEW%5B%22%E8%A7%86%E5%9B%BE%E4%B8%8D%E5%8F%AF%E5%8C%BA%E5%88%86%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"ZK 服务「选择性披露」：我属于集合、我付过款、我知道原像——验证者不带走可转述的证书。它不替代 TLS，不替代 AEAD。计算成本高，协议要选陈述。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},'常见误区：初学者容易把"零知识"听成"零信息"。实际对话信息量很大——它确实让你相信命题为真；"零"的只是关于证人的那部分。另一个误区是以为 ZK 能让传输加密：那仍是 TLS 的活，ZK 管的是证明本身。')],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},'数字实例：可靠性常写成"作弊成功率 ≤ 2 的负 k 次方"。挑战重复 k 轮，每轮猜中概率 1/2，k=80 时作弊概率约 10 的负 24 次方——把天文数字的反例压到工程上可以当作零。')],-1)),(t(),i(n,null,{default:e(()=>[l(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLAIM%5B%22%E5%91%BD%E9%A2%98%EF%BC%9A%E6%88%91%E7%9F%A5%E9%81%93%E8%AF%81%E4%BA%BA%22%5D%20--%3E%20R%7B%22%E9%AA%8C%E8%AF%81%E8%80%85%E5%8F%91%E9%9A%8F%E6%9C%BA%E6%8C%91%E6%88%98%22%7D%0A%20%20R%20--%3E%20P%5B%22%E8%AF%81%E6%98%8E%E8%80%85%E6%8C%89%E8%AF%81%E4%BA%BA%E5%BA%94%E7%AD%94%22%5D%0A%20%20P%20--%3E%20CHK%7B%22%E9%AA%8C%E8%AF%81%E8%80%85%E6%A0%B8%E5%AF%B9%22%7D%0A%20%20CHK%20--%3E%20PASS%5B%22%E5%AF%B9%EF%BC%9A%E9%80%9A%E8%BF%87%E6%9C%AC%E8%BD%AE%22%5D%0A%20%20CHK%20--%3E%20FAIL%5B%22%E9%94%99%EF%BC%9A%E8%AF%86%E7%A0%B4%E4%BD%9C%E5%BC%8A%22%5D%0A%20%20PASS%20--%3E%20MORE%7B%22%E8%BD%AE%E6%95%B0%E5%A4%9F%E4%BA%86%E5%90%97%22%7D%0A%20%20MORE%20--%3E%20YES%5B%22%E6%8E%A5%E5%8F%97%E5%91%BD%E9%A2%98%22%5D%0A%20%20MORE%20--%3E%20NO%5B%22%E5%86%8D%E5%8F%91%E6%8C%91%E6%88%98%22%5D%0A%20%20SIM%5B%22%E6%A8%A1%E6%8B%9F%E5%99%A8%E4%B8%8D%E7%9C%8B%E8%AF%81%E4%BA%BA%22%5D%20--%3E%20FAKE%5B%22%E4%BC%AA%E9%80%A0%E5%90%8C%E5%88%86%E5%B8%83%E5%AF%B9%E8%AF%9D%22%5D%0A%20%20FAKE%20--%3E%20ZERO%5B%22%E8%AF%81%E6%98%8E%E5%AF%B9%E8%AF%9D%E4%B8%8D%E6%B3%84%E6%BC%8F%E8%AF%81%E4%BA%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Groth16 的配对细节，不把区块链当必经应用。下一课承诺与 Merkle 树：隐藏后可打开，以及把集合收成根。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>KEM 换困难问题；ZK 换「证明而不给证人」。</li><li>完备、可靠、零知识三条分开。</li><li>模拟器测试零知识；转述性与签名不同。</li><li>下一课：承诺与 Merkle 树。</li><li>出处：Goldwasser, Micali and Rackoff, 1985/1989；对照 Goldreich。</li></ul>',4))])}const k=s(p,[["render",F]]);export{C as __pageData,k as default};
